var items = $input.all();
var item = items[0].json;

try {
  var prompt = 'Evalua este lead:\n' +
    '- Nombre: ' + (item.name || '') + '\n' +
    '- Email: ' + (item.email || '') + '\n' +
    '- Empresa: ' + (item.company || '') + '\n' +
    '- Sector: ' + (item.sector || '') + '\n' +
    '- Servicio: ' + (item.service || '') + '\n' +
    '- Presupuesto: ' + (item.budget || '') + '\n' +
    '- Web: ' + (item.website || '') + '\n' +
    '- Mensaje: ' + (item.message || '') + '\n' +
    '- Pagina origen: ' + (item.source_page || '') + '\n\n' +
    'Criterios: VIP(85-100) ALTO(65-84) MEDIO(40-64) BAJO(0-39)\n\n' +
    'Responde SOLO con un JSON valido: {"tier":"VIP|ALTO|MEDIO|BAJO","score":0-100,"reasoning":"2 frases","priority_action":"accion concreta","estimated_value":"importe EUR"}';

  var payload = {
    model: 'gpt-4o-mini',
    temperature: 0.15,
    max_tokens: 500,
    messages: [
      {role: 'system', content: 'Eres un motor de scoring de leads B2B para Zyndrix. Responde SIEMPRE con un unico objeto JSON valido. Sin markdown, sin backticks.'},
      {role: 'user', content: prompt}
    ]
  };

  var aiBody = JSON.stringify(payload);

  items[0].json.aiBody = aiBody;
  items[0].json.aiBody_len = aiBody.length;

} catch(e) {
  items[0].json.aiBody = '{}';
  items[0].json.aiBody_error = e.message || 'unknown error';
}

return items;
